/// Plain-data record for an attached file held in [_ChatInputState].
class _Attachment {
  final String name;
  final String path;
  final String content;
  final int byteSize;
  final bool truncated;

  const _Attachment({
    required this.name,
    required this.path,
    required this.content,
    required this.byteSize,
    required this.truncated,
  });
}

